const projetos=[{id:"cozinha-comunitaria",titulo:"Cozinha Comunitária",descricao:"A Cozinha Comunitária tem como objetivo preparar e distribuir refeições para pessoas que precisam de apoio.",detalhes:"O projeto conta com a participação de voluntários no preparo, organização e distribuição das refeições."},{id:"arrecadacao-alimentos",titulo:"Arrecadação de Alimentos",descricao:"O projeto de arrecadação busca reunir alimentos para apoiar famílias e pessoas atendidas pela FEED LIFE.",detalhes:"As doações podem ser realizadas por pessoas, empresas, mercados e outros parceiros interessados em contribuir."}];function criarProjeto(e){const o=document.createElement("article");return o.id=e.id,o.innerHTML=`\n        <h3>${e.titulo}</h3>\n\n        <p>${e.descricao}</p>\n\n        <p>${e.detalhes}</p>\n    `,o}const listaProjetos=document.querySelector("#lista-projetos");listaProjetos.innerHTML="",projetos.forEach(function(e){const o=criarProjeto(e);listaProjetos.appendChild(o)});const linksNavegacao=document.querySelectorAll("nav a");linksNavegacao.forEach(function(e){e.addEventListener("click",function(o){const t=e.getAttribute("href");if(!t.startsWith("#"))return;if(o.preventDefault(),"#"===t)return;const a=document.querySelector(t);if(!a)return;document.querySelectorAll("main section").forEach(function(e){e.style.display="none"});const r=a.closest("section");if(r&&(r.style.display="block","ARTICLE"===a.tagName)){r.querySelectorAll("article").forEach(function(e){e.style.display="none"}),a.style.display="block"}})});const botaoContraste=document.querySelector("#alto-contraste");botaoContraste&&botaoContraste.addEventListener("click",function(){document.body.classList.toggle("alto-contraste");const e=document.body.classList.contains("alto-contraste");botaoContraste.setAttribute("aria-pressed",e)});